DELETE FROM app.BancaFisierTransfer
WHERE CodSucursala = @CodSucursala
  AND Luna         = @Luna
  AND Anul         = @Anul
  AND (
        TRY_CAST(@DataPlatii AS DATE) IS NULL
        OR DataPlatii = TRY_CAST(@DataPlatii AS DATE)
      )
  AND (
        @TipPlata IS NULL
        OR @TipPlata = ''
        OR TipPlata = @TipPlata
      );
